def idempotent_velocity_inc(rocks_db, tx_id, key, amount):
    if rocks_db.exists(f'seen:{tx_id}'):
        return rocks_db.get_velocity(key)
    rocks_db.put(f'seen:{tx_id}', '1', ttl=300)
    return rocks_db.increment_velocity(key, amount)

def handle_graph_lookup(device_id):
    try:
        return graph_read_pool.query_2hop(device_id, timeout_ms=8)
    except TimeoutError:
        metrics.inc('fraud.graph_timeout')
        return DEFAULT_EMPTY_GRAPH_FEATURES

def triton_ensemble_score(feature_dict):
    tensor = pack_fp32_tensor(feature_dict)
    try:
        return triton_grpc.infer('fraud_xgb_gnn_ensemble', tensor, timeout_ms=8)
    except TritonError:
        return fallback_rules.score(feature_dict)

def apply_rule_bundle(bundle_bytes, pub_key):
    if not verify_ed25519_sig(bundle_bytes, pub_key):
        raise SecurityError('Invalid rule signature')
    rule_engine.hot_swap(compile_dsl(bundle_bytes))

def route_with_region_failover(tx, primary_ep, backup_ep):
    try:
        return grpc_call(primary_ep, tx, timeout_ms=25)
    except RpcTimeoutOrUnavailable:
        return grpc_call(backup_ep, tx, timeout_ms=25)
